import json
import subprocess
import sys
from pathlib import Path

REFERENCE = '# 판다스를 pd라는 이름으로 불러와요.\nimport pandas as pd\n# 제공 파일은 실행 폴더에 있어요. 첫 행은 열 이름이에요.\n# 이 줄의 파일 이름을 고쳐 제공된 배송 파일을 읽으세요.\n# read_csv는 실행 폴더에서 이 이름의 파일을 찾아 표로 읽어요.\ndf = pd.read_csv("delivery.csv")\nprint(df.shape)\n'
VARIANTS = json.loads('[{"delivery.csv": "order_id,minutes,region\\n201,7,부산\\n"}, {"delivery.csv": "order_id,minutes,region,distance\\n301,15,서울,2\\n302,9,부산,1\\n303,40,서울,5\\n304,11,부산,1\\n305,22,서울,3\\n"}, {"delivery.csv": "region,minutes,order_id\\n서울,50,401\\n부산,45,402\\n부산,8,403\\n"}]')
names = sorted({name for variant in VARIANTS for name in variant})
original = {name: Path(name).read_text(encoding="utf-8") if Path(name).exists() else None for name in names}
Path("_reference.py").write_text(REFERENCE, encoding="utf-8")
def run(script):
    return subprocess.run([sys.executable, "-I", "-X", "utf8", script], stdin=subprocess.DEVNULL, capture_output=True,
                          text=True, encoding="utf-8", timeout=60)
try:
    for variant in VARIANTS:
        for name, text in variant.items():
            Path(name).write_text(text, encoding="utf-8")
        expected = run("_reference.py")
        if expected.returncode != 0:
            raise RuntimeError("준비한 검사 자료를 읽지 못했어요: " + expected.stderr[-300:])
        actual = run("main.py")
        if actual.returncode != 0 or actual.stdout.strip() != expected.stdout.strip():
            raise AssertionError('다른 배송 파일에서도 같은 원리로 맞는 결과가 나와야 해요.')
finally:
    for name, text in original.items():
        if text is None:
            Path(name).unlink(missing_ok=True)
        else:
            Path(name).write_text(text, encoding="utf-8")
    Path("_reference.py").unlink(missing_ok=True)
print(f"바꾼 자료 {len(VARIANTS)}개에서도 통과했어요.")

